body {
  margin: 0;
  background: #f5f7fb;
  color: #101828;
  font-family: Inter, Arial, sans-serif;
}

.page {
  padding: 16px;
  box-sizing: border-box;
}

.toolbar {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  background: #101828;
  color: white;
  border-radius: 8px;
  padding: 16px;
}

.toolbar span {
  color: #98a2b3;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.toolbar h1 {
  margin: 4px 0;
  font-size: 26px;
  line-height: 1.1;
}

.toolbar p {
  margin: 0;
  color: #d0d5dd;
  font-size: 12px;
}

button {
  height: 38px;
  border: 0;
  border-radius: 7px;
  background: #ffffff;
  color: #101828;
  font-weight: 900;
  padding: 0 14px;
  cursor: pointer;
}

.profile,
.kpis {
  display: grid;
  gap: 10px;
  margin-top: 12px;
}

.profile {
  grid-template-columns: 1.1fr 1.4fr 0.8fr;
}

.kpis {
  grid-template-columns: repeat(5, 1fr);
}

.profile > div,
.kpis > div,
section {
  background: white;
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  padding: 12px;
}

.profile span,
.kpis span {
  display: block;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 900;
  margin-bottom: 5px;
}

.profile strong {
  display: block;
  font-size: 13px;
}

.kpis strong {
  display: block;
  font-size: 19px;
}

.kpis .warn {
  border-color: #f97316;
  border-left: 5px solid #f97316;
}

.split {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 12px;
  margin-top: 12px;
}

.section-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.section-head h2 {
  margin: 0;
  font-size: 16px;
}

.section-head span {
  color: #667085;
  font-size: 12px;
  font-weight: 800;
}

.timeline,
.items {
  display: grid;
  gap: 7px;
}

.timeline-row,
.item-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid #eaecf0;
  border-radius: 7px;
  padding: 9px;
  align-items: center;
}

.timeline-row b,
.item-row b {
  display: block;
  font-size: 13px;
}

.timeline-row span,
.item-row span,
.item-numbers span {
  display: block;
  color: #667085;
  font-size: 11px;
  margin-top: 2px;
}

.timeline-row strong,
.item-numbers strong {
  white-space: nowrap;
  font-size: 13px;
}

.item-numbers {
  text-align: right;
}

.trend-section {
  margin-top: 12px;
}

.trend {
  height: 190px;
  display: flex;
  gap: 8px;
  align-items: flex-end;
  border-top: 1px solid #eaecf0;
  padding-top: 12px;
}

.bar-wrap {
  flex: 1;
  min-width: 34px;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  text-align: center;
}

.bar {
  background: #2563eb;
  min-height: 8px;
  border-radius: 6px 6px 0 0;
  position: relative;
}

.bar span {
  position: absolute;
  left: 50%;
  bottom: 100%;
  transform: translateX(-50%);
  margin-bottom: 4px;
  font-size: 10px;
  color: #344054;
  white-space: nowrap;
}

.bar-wrap small {
  margin-top: 5px;
  color: #667085;
  font-size: 10px;
}

.footer {
  margin-top: 12px;
  color: #667085;
  font-size: 10px;
  text-align: center;
}

.empty {
  background: white;
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  padding: 28px;
  text-align: center;
  color: #667085;
}

.empty h1 {
  margin: 0 0 6px;
  color: #101828;
}

.empty p {
  margin: 0;
}

@media print {
  body {
    background: white;
  }
  .page {
    padding: 0;
  }
  button {
    display: none;
  }
  .toolbar,
  .profile > div,
  .kpis > div,
  section {
    box-shadow: none;
  }
}

