import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

function money(value) {
  return Number(value || 0).toFixed(2);
}

function qty(value) {
  return Number(value || 0).toFixed(2);
}

function date(value) {
  if (!value) return "-";
  return new Date(value).toLocaleDateString("en-GB");
}

function shortType(type) {
  const value = String(type || "").toUpperCase();

  if (value === "SALES_INVOICE") return "Invoice";
  if (value === "CREDIT_NOTE") return "Credit";
  if (value === "SALES_ORDER") return "Order";
  if (value === "DELIVERY_NOTE") return "Delivery";
  if (value === "QUOTE") return "Quote";

  return value || "-";
}

function App() {
  const model = appsmith.model || {};
  const overview = model.overview || {};
  const documents = model.documents || [];
  const topItems = model.topItems || [];
  const monthlyTrend = model.monthlyTrend || [];

  const maxTrend = Math.max(...monthlyTrend.map(row => Number(row.totalAmount || 0)), 1);

  if (!overview.customerId) {
    return (
      <div className="empty">
        <h1>Customer 360</h1>
        <p>Select a customer to view sales, balance, documents and buying history.</p>
      </div>
    );
  }

  return (
    <div className="page">
      <div className="toolbar">
        <div>
          <span>Customer 360</span>
          <h1>{overview.customerName || "-"}</h1>
          <p>
            {[overview.customerCode, overview.taxNumber, overview.email, overview.phone]
              .filter(Boolean)
              .join(" | ")}
          </p>
        </div>

        <button onClick={() => window.print()}>Print Statement</button>
      </div>

      <div className="profile">
        <div>
          <span>Legal Name</span>
          <strong>{overview.legalName || overview.customerName || "-"}</strong>
        </div>
        <div>
          <span>Address</span>
          <strong>
            {[overview.address, overview.postalCode, overview.city].filter(Boolean).join(", ") || "-"}
          </strong>
        </div>
        <div>
          <span>Period</span>
          <strong>{model.dateFrom || "-"} - {model.dateTo || "-"}</strong>
        </div>
      </div>

      <div className="kpis">
        <div>
          <span>Total Sales</span>
          <strong>{money(overview.totalSales)} EUR</strong>
        </div>
        <div>
          <span>Paid</span>
          <strong>{money(overview.totalPaid)} EUR</strong>
        </div>
        <div className={Number(overview.openAmount || 0) > 0 ? "warn" : ""}>
          <span>Open Amount</span>
          <strong>{money(overview.openAmount)} EUR</strong>
        </div>
        <div>
          <span>Documents</span>
          <strong>{overview.documentCount || 0}</strong>
        </div>
        <div>
          <span>Last Invoice</span>
          <strong>{date(overview.lastInvoiceDate)}</strong>
        </div>
      </div>

      <div className="split">
        <section>
          <div className="section-head">
            <h2>Document Timeline</h2>
            <span>{documents.length} documents</span>
          </div>

          <div className="timeline">
            {documents.slice(0, 10).map((doc, index) => (
              <div className="timeline-row" key={index}>
                <div>
                  <b>{doc["Document Number"]}</b>
                  <span>{shortType(doc.documentType)} | {date(doc["Document Date"])} | {doc.Status || "-"}</span>
                </div>
                <strong>{money(doc.Total)} {doc.Currency || "EUR"}</strong>
              </div>
            ))}
          </div>
        </section>

        <section>
          <div className="section-head">
            <h2>Top Items</h2>
            <span>{topItems.length} items</span>
          </div>

          <div className="items">
            {topItems.slice(0, 8).map((item, index) => (
              <div className="item-row" key={index}>
                <div>
                  <b>{item.productCode || "-"}</b>
                  <span>{item.productName || "Item"}</span>
                </div>
                <div className="item-numbers">
                  <strong>{money(item.totalAmount)} EUR</strong>
                  <span>{qty(item.quantity)} qty</span>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>

      <section className="trend-section">
        <div className="section-head">
          <h2>Monthly Sales Trend</h2>
          <span>{monthlyTrend.length} periods</span>
        </div>

        <div className="trend">
          {monthlyTrend.map((row, index) => {
            const height = Math.max(8, (Number(row.totalAmount || 0) / maxTrend) * 100);

            return (
              <div className="bar-wrap" key={index}>
                <div className="bar" style={{ height: `${height}%` }}>
                  <span>{money(row.totalAmount)}</span>
                </div>
                <small>{row.monthKey}</small>
              </div>
            );
          })}
        </div>
      </section>

      <div className="footer">
        Printed: {model.printedAt || "-"} {model.printedBy ? `by ${model.printedBy}` : ""}
      </div>
    </div>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
